const std::size_t group_size = binfo->group_size;
const std::size_t group_mask = group_size - 1;
const std::size_t nbits = binfo->nbits;
const std::size_t group_count = (nbits + group_size - 1) / group_size;

std::size_t start_group = min_bit / group_size;
std::size_t start_offset = min_bit & group_mask;

for (std::size_t group = start_group; group < group_count; ++group) {
    const std::uint64_t *group_ptr = bitmap + group * (group_size / std::size_t(64));
    std::size_t offset = (group == start_group) ? start_offset : 0;

    for (; offset < group_size; ++offset) {
        std::size_t bit_pos = group * group_size + offset;
        if (bit_pos >= nbits) {
            continue;
        }

        std::size_t word_idx = offset / 64;
        std::size_t bit_in_word = offset % 64;
        if (!(group_ptr[word_idx] & (std::uint64_t(1) << bit_in_word))) {
            return bit_pos;
        }
    }
}

return nbits;
// END_CODE

